import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv with no invoices returns header only', () => {
  const csv = exportCsv([]);
  assert.equal(csv, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv includes header line', () => {
  const csv = exportCsv([]);
  assert.equal(csv.startsWith('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n'), true);
});

test('exportCsv each line ends with newline', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  assert.equal(lines[lines.length - 1], '');
  assert.equal(lines.every((line, i) => i === lines.length - 1 || line), true);
});

test('exportCsv formats single invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3);
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.match(lines[1], /^INV-/);
});

test('exportCsv includes all required columns', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields.length, 10);
});

test('exportCsv formats amounts as plain euros with 2 decimals', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  assert.match(dataLine, /\d+\.\d{2}/);
  assert.notMatch(dataLine, /€/);
  assert.notMatch(dataLine, /\d,\d{3}/);
});

test('exportCsv uses customer name not ID', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  assert.match(dataLine, /Acme/);
});

test('exportCsv quotes field with comma', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  issued.value.customerName = 'Smith, John';
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  assert.match(dataLine, /"Smith, John"/);
});

test('exportCsv doubles internal quotes and wraps field', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  issued.value.customerName = 'Company "ABC" Inc';
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  assert.match(dataLine, /"Company ""ABC"" Inc"/);
});

test('exportCsv with multiple invoices in order', () => {
  const draft1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const draft2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'STICKER', qty: 5 }],
  });
  const issued1 = issueInvoice(draft1.value, []);
  const issued2 = issueInvoice(draft2.value, ['INV-2026-0001']);
  const csv = exportCsv([issued1.value, issued2.value]);
  const lines = csv.split('\n');
  assert.equal(lines.length, 4);
  assert.match(lines[1], /Acme/);
  assert.match(lines[2], /Zenith/);
});

test('exportCsv calculates correct totals', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(draft.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[5], (totals.subtotal / 100).toFixed(2));
  assert.equal(fields[6], (totals.discount / 100).toFixed(2));
  assert.equal(fields[7], (totals.vat / 100).toFixed(2));
  assert.equal(fields[8], (totals.total / 100).toFixed(2));
});

test('exportCsv shows invoice status', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  assert.match(dataLine, /issued/);
});

test('exportCsv shows due amount for unpaid invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[9], (totals.total / 100).toFixed(2));
});

test('exportCsv shows remaining due for partially paid invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const paymentAmount = 5000;
  const partial = recordPayment(issued.value, { amount: paymentAmount, date: '2026-10-08' });
  const totals = invoiceTotals(issued.value);
  const expectedDue = totals.total - paymentAmount;
  const csv = exportCsv([partial.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[9], (expectedDue / 100).toFixed(2));
});

test('exportCsv shows zero due for fully paid invoice', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });
  const csv = exportCsv([paid.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[9], '0.00');
});

test('exportCsv with no discount shows 0.00', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'STICKER', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[6], '0.00');
});

test('exportCsv with discount shows correct amount', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1, discountPercent: 50 }],
  });
  const issued = issueInvoice(draft.value, []);
  const totals = invoiceTotals(issued.value);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  const fields = dataLine.split(',');
  assert.equal(fields[6], (totals.discount / 100).toFixed(2));
});

test('exportCsv with different currencies and large amounts', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'LOGO-PACK', qty: 5 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  assert.notMatch(dataLine, /€/);
  assert.notMatch(dataLine, /,\d{3}/);
  assert.match(dataLine, /\d+\.\d{2}/);
});

test('exportCsv handles invoice number that might need quoting', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.split('\n');
  const dataLine = lines[1];
  assert.match(dataLine, /^INV-\d{4}-\d{4}/);
});

test('exportCsv returns string ending with newline', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  assert.equal(csv.endsWith('\n'), true);
});

test('exportCsv can be parsed as valid CSV', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(draft.value, []);
  const csv = exportCsv([issued.value]);
  const lines = csv.trim().split('\n');
  assert.equal(lines.length, 2);
  const headerFields = lines[0].split(',');
  assert.equal(headerFields.length, 10);
});

